package com.emp.ems;
import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.CommandLineRunner;import org.springframework.core.env.Environment;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Component public class Bootstrap implements CommandLineRunner{private final EmployeeRepository employees;private final LeaveRepository leaves;private final EventRepository events;private final TaskRepository tasks;private final PeopleController people;private final PasswordEncoder encoder;private final Environment environment;@Value("${ems.demo-password}")String demoPassword;@Value("${ems.admin-email}")String adminEmail;@Value("${ems.admin-password}")String adminPassword;Bootstrap(EmployeeRepository employees,LeaveRepository leaves,EventRepository events,TaskRepository tasks,PeopleController people,PasswordEncoder encoder,Environment environment){this.employees=employees;this.leaves=leaves;this.events=events;this.tasks=tasks;this.people=people;this.encoder=encoder;this.environment=environment;}
 @Override @Transactional public void run(String...args){if(Arrays.asList(environment.getActiveProfiles()).contains("demo")&&employees.count()==0){if(demoPassword.length()<12||demoPassword.length()>72)throw new IllegalStateException("Demo profile requires EMS_DEMO_PASSWORD with 12–72 characters.");seed();}if(!adminEmail.isBlank()&&!employees.existsByEmailIgnoreCase(adminEmail)){if(adminPassword.length()<12||adminPassword.length()>72)throw new IllegalStateException("ADMIN_PASSWORD must have 12–72 characters.");Employee e=new Employee();e.name="Workspace Admin";e.email=adminEmail.trim().toLowerCase(Locale.ROOT);e.passwordHash=encoder.encode(adminPassword);e.title="People & Culture Lead";e.department="People";e.role="ADMIN";e.status="Active";employees.save(e);}}
 void seed(){String hash=encoder.encode(demoPassword);String[][] data={{"Ethan Parker","Software Engineer","Engineering","2","Active"},{"Liam Carter","UI/UX Designer","Design","3","On leave"},{"Noah Mitchell","Backend Developer","Engineering","4","Active"},{"Ava Thompson","Product Manager","Product","1","On leave"},{"Mia Robinson","QA Engineer","Engineering","1","Active"},{"Oliver Wilson","Marketing Lead","Marketing","3","Active"},{"Sophia Adams","UI/UX Designer","Design","1","Onboarding"},{"Lucas Morgan","Mobile Developer","Engineering","4","Onboarding"},{"Mason Reed","Cloud Architect","Engineering","2","Onboarding"},{"Justin Crown","Content Designer","Marketing","3","Onboarding"},{"Emily Bennett","People & Culture Lead","People","1","Active"},{"Isabella Lee","Finance Manager","Finance","1","Active"}};List<Employee> list=new ArrayList<>();int c=0;for(String[] row:data){Employee e=new Employee();e.name=row[0];e.title=row[1];e.department=row[2];e.avatar=Integer.parseInt(row[3]);e.status=row[4];e.email=e.name.split(" ")[0].toLowerCase()+"@forma.team";e.passwordHash=hash;if(e.name.startsWith("Emily"))e.role="ADMIN";employees.save(e);list.add(e);if(e.status.equals("Onboarding")){people.seedTasks(e);var steps=tasks.findByEmployeeIdOrderBySortOrder(e.id);int complete=new int[]{5,7,3,8}[c++];for(int i=0;i<complete;i++)steps.get(i).done=true;}}
 LocalDate monday=LocalDate.now().with(java.time.temporal.TemporalAdjusters.previousOrSame(DayOfWeek.MONDAY));String[] kinds={"Vacation","Paid leave","Sick leave","Vacation","Paid leave","Vacation"};int[] starts={10,1,4,0,10,7},ends={13,4,8,3,13,9};for(int i=0;i<6;i++){LeaveRequest l=new LeaveRequest();l.employee=list.get(i);l.type=kinds[i];l.startDate=monday.plusDays(starts[i]);l.endDate=monday.plusDays(ends[i]);l.status=i==2||i==4?"Pending":"Approved";leaves.save(l);}String[][] upcoming={{"Tech Innovations Summit","Big ideas. Fresh perspectives. What’s next.","14:00 – 15:00"},{"Design & Coffee","A little inspiration, a great conversation.","10:00 – 11:00"},{"End-of-year Town Hall","Celebrating the things we made happen.","15:00 – 16:00"}};for(int i=0;i<3;i++){WorkspaceEvent e=new WorkspaceEvent();e.title=upcoming[i][0];e.description=upcoming[i][1];e.time=upcoming[i][2];e.date=monday.plusDays(i*2);e.attendees=i==0?8:12;if(i==0)e.tag="Coming up";events.save(e);}}
}
